
create unique index if not exists interview_questions_question_key on public.interview_questions (lower(question));

insert into public.interview_questions (category, difficulty, question, suggested_answer, tags) values
-- JavaScript
('javascript', 'easy', $$What is the difference between let, const and var?$$,
 $$var is function-scoped and hoisted (initialised as undefined). let and const are block-scoped and sit in the "temporal dead zone" until declared. const can't be reassigned, but an object it holds can still be changed. Use const by default, let when you need to reassign, and avoid var.$$, array['JavaScript']),
('javascript', 'easy', $$Explain == versus ===.$$,
 $$== compares after type coercion ('5' == 5 is true), while === compares value and type without coercion. Prefer === to avoid surprising conversions; "x == null" is a common deliberate exception to check for null or undefined at once.$$, array['JavaScript']),
('javascript', 'medium', $$What is a closure? Give an example of when it's useful.$$,
 $$A closure is a function that remembers the variables of the scope where it was created, even after that scope has finished. Example: function counter() { let n = 0; return () => ++n; }. Closures give you private state, function factories, memoisation and event handlers that keep context.$$, array['JavaScript']),
('javascript', 'medium', $$Explain the JavaScript event loop.$$,
 $$JavaScript runs on one thread with a call stack. Async work (timers, network, I/O) is handled by the browser or Node, and its callbacks are queued. When the stack is empty, all microtasks (promise callbacks) run first, then the next macrotask (setTimeout, events). That's why Promise.then runs before setTimeout(fn, 0).$$, array['JavaScript']),
('javascript', 'medium', $$How is the value of `this` determined?$$,
 $$It depends on how a function is called: as a method, this is the object; as a plain function, it's undefined in strict mode; with new, it's the new instance; call, apply and bind set it explicitly. Arrow functions don't have their own this — they use the surrounding scope's.$$, array['JavaScript']),
('javascript', 'hard', $$Promises versus async/await — and how do you handle errors?$$,
 $$A Promise represents a future value that is pending, fulfilled or rejected. async/await is syntax on top of promises that reads like synchronous code. Handle errors with try/catch around await (or .catch on the promise). Use Promise.all for parallel work and Promise.allSettled when some tasks may fail.$$, array['JavaScript', 'TypeScript']),
('javascript', 'hard', $$What is the difference between debounce and throttle?$$,
 $$Debounce waits until calls stop for N ms, then runs once — ideal for search-as-you-type. Throttle runs at most once every N ms during continuous calls — ideal for scroll or resize handlers. Both limit how often expensive work runs.$$, array['JavaScript', 'Performance optimization']),

-- React
('react', 'easy', $$What are props and state in React?$$,
 $$Props are read-only inputs passed from a parent component. State is data a component owns and changes over time (useState), and changing it triggers a re-render. When siblings need the same data, lift the state up to their common parent.$$, array['React']),
('react', 'easy', $$Why does React need a key when rendering a list?$$,
 $$Keys let React match list items between renders, so it keeps the right state and DOM node with the right item. Use a stable unique id; avoid the array index when items can be reordered, inserted or removed.$$, array['React']),
('react', 'medium', $$Explain useEffect and its dependency array.$$,
 $$useEffect runs side effects after render — data fetching, subscriptions, timers. The dependency array decides when it re-runs: [] once after mount, [a, b] when those values change, no array on every render. Return a cleanup function to unsubscribe or cancel. Values you can calculate during render don't need an effect.$$, array['React']),
('react', 'medium', $$What is the difference between controlled and uncontrolled components?$$,
 $$A controlled input gets its value from React state and updates through onChange, so React is the source of truth — easy to validate and transform. An uncontrolled input keeps its own value in the DOM and you read it with a ref or FormData — less code for simple forms.$$, array['React']),
('react', 'medium', $$When would you use useMemo, useCallback and React.memo?$$,
 $$useMemo caches an expensive calculation, useCallback keeps a function's identity stable (for memoised children or effect dependencies), and React.memo skips re-rendering a component when its props haven't changed. Measure first — unnecessary memoisation adds complexity without benefit.$$, array['React', 'Performance optimization']),
('react', 'hard', $$How do you manage global state in a React app?$$,
 $$Start with local state and lifting state up. Use Context for low-frequency shared data such as the logged-in user or theme. For complex, frequently-updated client state use a store like Redux Toolkit or Zustand. Treat server data separately with a fetching/caching layer (e.g. TanStack Query) instead of copying it into global state.$$, array['React', 'Redux']),

-- HTML
('html', 'easy', $$What is semantic HTML and why does it matter?$$,
 $$Semantic HTML uses elements that describe meaning — header, nav, main, article, button, label — instead of generic divs. It helps screen-reader and keyboard users, improves SEO and makes code easier to read.$$, array['HTML', 'Web accessibility']),
('html', 'easy', $$What is the difference between block and inline elements?$$,
 $$Block elements (div, p, section) start on a new line and take the full width. Inline elements (span, a, strong) flow inside text and only take the width they need. inline-block flows inline but accepts width and height.$$, array['HTML', 'CSS']),
('html', 'medium', $$How do you make a form accessible?$$,
 $$Give every input a visible label connected with for/id, group related fields with fieldset and legend, use the right input types, show errors as text linked with aria-describedby, don't rely on colour alone, and make sure everything works with the keyboard and has visible focus styles.$$, array['HTML', 'Web accessibility']),
('html', 'medium', $$What do the async and defer attributes do on a script tag?$$,
 $$Both download the script without blocking HTML parsing. async runs it as soon as it's downloaded, in no guaranteed order — good for independent scripts like analytics. defer runs it after parsing finishes, in document order — good for app code. type="module" scripts are deferred by default.$$, array['HTML', 'JavaScript']),
('html', 'medium', $$Compare localStorage, sessionStorage and cookies.$$,
 $$localStorage persists until cleared; sessionStorage lasts for the browser tab's session. Both hold about 5 MB, are readable by JavaScript and are not sent to the server. Cookies are small (about 4 KB), are sent with every request and can be HttpOnly, Secure and SameSite — which makes them better for auth sessions.$$, array['HTML', 'Web security']),
('html', 'hard', $$What is the critical rendering path, and how do you optimise it?$$,
 $$The browser parses HTML into the DOM and CSS into the CSSOM, combines them into a render tree, calculates layout, then paints. Speed it up by reducing render-blocking CSS and JavaScript, inlining critical CSS, deferring scripts, compressing assets and lazy-loading images below the fold.$$, array['HTML', 'Performance optimization']),

-- CSS
('css', 'easy', $$Explain the CSS box model.$$,
 $$Every element is made of content, padding, border and margin. With box-sizing: border-box, the width you set includes padding and border, which makes layouts much easier to reason about.$$, array['CSS']),
('css', 'easy', $$When would you use Flexbox and when Grid?$$,
 $$Flexbox lays items out in one dimension — a row or a column — and is great for navbars and aligning items. Grid handles two dimensions at once, rows and columns, and is great for page layouts and card grids. They work well together.$$, array['CSS']),
('css', 'medium', $$How does CSS specificity work?$$,
 $$Inline styles beat IDs, IDs beat classes/attributes/pseudo-classes, and those beat element selectors. If specificity is equal, the later rule wins. !important overrides normal rules but makes CSS hard to maintain — keep specificity low instead.$$, array['CSS']),
('css', 'medium', $$Explain the position values static, relative, absolute, fixed and sticky.$$,
 $$static is the normal flow. relative offsets an element from its normal spot and becomes a positioning context. absolute removes it from the flow and positions it against the nearest positioned ancestor. fixed positions it against the viewport. sticky behaves like relative until a scroll threshold, then sticks.$$, array['CSS']),
('css', 'medium', $$How do you build a responsive layout?$$,
 $$Write mobile-first styles, then add media queries (or container queries) for larger screens. Use fluid units (%, rem, fr, clamp()), flexible images (max-width: 100%), and Flexbox/Grid with wrapping. Test on real device sizes.$$, array['CSS', 'Responsive design']),
('css', 'hard', $$Name three ways to centre an element horizontally and vertically.$$,
 $$Flexbox: on the parent, display: flex; align-items: center; justify-content: center. Grid: display: grid; place-items: center. Absolute positioning: top: 50%; left: 50%; transform: translate(-50%, -50%). Pick the one that fits the surrounding layout.$$, array['CSS']),

-- Node.js
('nodejs', 'easy', $$What is Node.js, and why is it a good fit for APIs?$$,
 $$Node.js is a JavaScript runtime built on Chrome's V8 engine with non-blocking, event-driven I/O. A single thread can handle many concurrent connections efficiently, which suits I/O-heavy APIs. CPU-heavy work belongs in worker threads or a separate service.$$, array['Node.js']),
('nodejs', 'easy', $$What is middleware in Express?$$,
 $$Middleware are functions (req, res, next) that run in order for each request — parsing bodies, authentication, logging, validation. Each one either ends the response or calls next() to continue. Error-handling middleware takes four arguments (err, req, res, next).$$, array['Node.js', 'Express.js']),
('nodejs', 'medium', $$How do you handle errors in an Express API?$$,
 $$Throw errors (or pass them to next(err)) and handle them in one central error middleware that maps them to status codes and a consistent JSON shape. Validate input early, log details on the server, and never send stack traces to clients in production. Express 5 forwards errors from async handlers automatically.$$, array['Node.js', 'Express.js']),
('nodejs', 'medium', $$How do you manage configuration and secrets in a Node.js app?$$,
 $$Use environment variables — a .env file in development and the hosting platform's settings in production — and validate them at startup. Never commit .env files, keep secrets only on the server, and rotate any key that leaks.$$, array['Node.js', 'Web security']),
('nodejs', 'medium', $$CommonJS versus ES modules — what's the difference?$$,
 $$CommonJS uses require and module.exports and loads synchronously. ES modules use import/export, can be statically analysed (enabling tree-shaking) and support top-level await. Enable them with "type": "module" in package.json or .mjs files; most new code uses ES modules.$$, array['Node.js', 'JavaScript']),
('nodejs', 'hard', $$How would you scale a Node.js API?$$,
 $$Keep the API stateless so you can run several instances behind a load balancer. Cache hot data (e.g. Redis), add database indexes and connection pooling, move slow jobs to a queue with workers, add rate limiting, and monitor latency and error rates to find the real bottleneck.$$, array['Node.js', 'System design']),

-- SQL
('sql', 'easy', $$What is the difference between WHERE and HAVING?$$,
 $$WHERE filters rows before grouping. HAVING filters groups after GROUP BY, usually on aggregates — for example HAVING COUNT(*) > 5.$$, array['SQL']),
('sql', 'easy', $$Explain INNER JOIN versus LEFT JOIN.$$,
 $$INNER JOIN returns only rows that have a match in both tables. LEFT JOIN returns every row from the left table plus matching rows from the right table, with NULLs where there is no match.$$, array['SQL']),
('sql', 'medium', $$What is an index, and when would you add one?$$,
 $$An index (usually a B-tree) is a structure that speeds up lookups, like the index of a book. Add one on columns used in WHERE, JOIN and ORDER BY. The trade-off is slower writes and extra storage, so check the query plan with EXPLAIN before and after.$$, array['SQL', 'PostgreSQL']),
('sql', 'medium', $$What is database normalisation?$$,
 $$Organising tables to reduce duplication and update anomalies: atomic values (1NF), no partial dependencies on a composite key (2NF), and no dependencies between non-key columns (3NF). Sometimes you denormalise deliberately for read performance.$$, array['SQL']),
('sql', 'medium', $$What are transactions and what does ACID mean?$$,
 $$A transaction groups statements so they all succeed or all fail. ACID stands for Atomicity, Consistency, Isolation and Durability. Classic example: a money transfer debits one account and credits another inside one transaction.$$, array['SQL', 'PostgreSQL']),
('sql', 'hard', $$Write a query to find the second-highest salary.$$,
 $$SELECT MAX(salary) FROM employees WHERE salary < (SELECT MAX(salary) FROM employees); — or with a window function: SELECT DISTINCT salary FROM (SELECT salary, DENSE_RANK() OVER (ORDER BY salary DESC) AS r FROM employees) t WHERE r = 2;$$, array['SQL']),

-- REST APIs
('rest_api', 'easy', $$What makes an API RESTful?$$,
 $$Resources identified by URLs (/applications/42), standard HTTP methods for actions (GET, POST, PUT/PATCH, DELETE), stateless requests, representations such as JSON, and meaningful status codes.$$, array['REST APIs']),
('rest_api', 'easy', $$Explain the most common HTTP status codes.$$,
 $$200 OK, 201 Created, 204 No Content; 400 Bad Request (invalid input), 401 Unauthorized (not logged in), 403 Forbidden (no permission), 404 Not Found, 409 Conflict, 422 validation errors; 500 Internal Server Error.$$, array['REST APIs']),
('rest_api', 'medium', $$What is the difference between PUT and PATCH?$$,
 $$PUT replaces the whole resource and is idempotent. PATCH changes only the fields you send. POST on a collection creates a new resource.$$, array['REST APIs']),
('rest_api', 'medium', $$How do you secure a REST API?$$,
 $$HTTPS everywhere; authenticate every request (e.g. JWT or sessions) and check authorisation for the specific resource; validate and sanitise input; rate-limit; restrict CORS to known origins; give the database user the least privileges; hide internal error details; keep dependencies updated.$$, array['REST APIs', 'Authentication', 'Web security']),
('rest_api', 'medium', $$How would you paginate a large list endpoint?$$,
 $$Offset pagination (?page=2&pageSize=20) is simple and supports page numbers but slows down on deep pages. Cursor pagination (?after=<id>) is stable and fast, great for infinite scroll. Return metadata such as the total count or the next cursor.$$, array['REST APIs']),
('rest_api', 'hard', $$What is idempotency and why does it matter?$$,
 $$An idempotent request has the same effect whether it's sent once or many times — GET, PUT and DELETE should be. It matters because clients retry on network failures. For non-idempotent actions like payments, accept an idempotency key so a retry doesn't charge twice.$$, array['REST APIs', 'System design']),

-- Git
('git', 'easy', $$What is the difference between git merge and git rebase?$$,
 $$Merge combines branches with a merge commit and keeps the full history. Rebase replays your commits on top of another branch for a straight, linear history. Never rebase a shared branch that others have already pulled.$$, array['Git']),
('git', 'easy', $$What is a pull request?$$,
 $$A request to merge one branch into another, where teammates review the changes, discuss them and automated checks run before anything is merged.$$, array['Git', 'GitHub', 'Code review']),
('git', 'medium', $$How do you resolve a merge conflict?$$,
 $$Git marks the conflicting sections in the file. Edit it to keep the correct code, remove the conflict markers, run the tests, then git add the file and commit (or continue the rebase). Talk to whoever changed the same code if the right answer isn't obvious.$$, array['Git']),
('git', 'medium', $$git reset versus git revert?$$,
 $$git reset moves the branch pointer back and rewrites history — fine for local, unpushed work. git revert creates a new commit that undoes an earlier one, which is safe on shared branches.$$, array['Git']),
('git', 'medium', $$Describe a branching strategy you have used.$$,
 $$For example: main holds stable releases, dev is the integration branch, and each feature gets a feature/* branch from dev that is merged back through a reviewed pull request after tests pass. Urgent production fixes use hotfix/* branches from main. This keeps main always releasable.$$, array['Git', 'GitHub']),
('git', 'hard', $$How do you undo a commit that has already been pushed?$$,
 $$If others may have pulled it, run git revert <commit> and push the new commit. Only rewrite history (reset plus force-push) on a private branch, and use --force-with-lease so you don't overwrite someone else's work.$$, array['Git']),

-- HR
('hr', 'easy', $$Tell me about yourself.$$,
 $$Go present → past → future in about 90 seconds: what you do now and your key strengths, one or two relevant achievements or projects, and why this role is the right next step. Keep it focused on the job, not your whole life story.$$, array['Communication']),
('hr', 'easy', $$Why do you want to work here?$$,
 $$Show you've done research: mention something specific about the product, mission, tech stack or culture, and connect it to your skills and goals. Specific beats generic praise.$$, array['Communication']),
('hr', 'easy', $$What are your strengths and weaknesses?$$,
 $$Pick a strength that matters for the role and back it with a short example. For the weakness, choose a real but non-critical one and explain what you're doing about it — for example: "I used to over-polish work; now I timebox and ask for feedback early."$$, array['Communication']),
('hr', 'medium', $$Where do you see yourself in five years?$$,
 $$Show ambition that fits the role: deepening your technical skills, owning bigger features, perhaps mentoring others — without suggesting you plan to leave soon.$$, array['Communication', 'Leadership']),
('hr', 'medium', $$What are your salary expectations?$$,
 $$Research market ranges for the role, level and city beforehand. Give a range based on that research, say you're flexible for the right overall package, and it's fine to ask for their budget first.$$, array['Communication']),
('hr', 'medium', $$Why are you leaving your current job — or, as a fresher, why should we hire you?$$,
 $$Stay positive and talk about what you're moving towards (growth, new challenges), not complaints about your current employer. As a fresher, point to your projects, how quickly you learn, and your enthusiasm for this specific role.$$, array['Communication']),

-- Behavioural
('behavioral', 'medium', $$Tell me about a challenging project you worked on.$$,
 $$Use the STAR method — Situation, Task, Action, Result. Pick a real technical challenge, explain the specific actions and decisions you took, quantify the result if you can, and end with what you learned.$$, array['Problem solving', 'Communication']),
('behavioral', 'medium', $$Describe a time you disagreed with a teammate.$$,
 $$Show respectful collaboration: you listened to their view, compared options with data or trade-offs, agreed on a decision (even if it wasn't yours) and kept a good working relationship. Finish with the outcome.$$, array['Teamwork', 'Communication']),
('behavioral', 'medium', $$Tell me about a time you made a mistake.$$,
 $$Own it briefly, then focus on how you fixed it and what you changed afterwards — a test, a checklist, a review step. This shows accountability and growth.$$, array['Ownership', 'Problem solving']),
('behavioral', 'medium', $$How do you handle tight deadlines?$$,
 $$Clarify priorities and scope, break the work into steps, flag risks early, deliver the must-haves first and avoid shortcuts that create bugs. Back it up with a real example.$$, array['Time management']),
('behavioral', 'medium', $$Tell me about a time you had to learn something new quickly.$$,
 $$Describe the situation, how you learned (official docs, small prototypes, asking experienced people) and how you applied it successfully. Building a full-stack project like this one is a great example to use.$$, array['Problem solving', 'Ownership']),
('behavioral', 'hard', $$Describe a time you showed leadership without having a formal title.$$,
 $$For example: improving a team process, mentoring a classmate or colleague, or organising a project. Explain the initiative you took, how you got others on board, and the measurable result.$$, array['Leadership', 'Teamwork'])
on conflict do nothing;
